def unpad(padded_text):
    # Convert the padded text into a list of bytes for easier manipulation
    padded_bytes = bytearray(padded_text, 'utf-8')

    # Handle the case where the input is already unpadded
    if len(padded_text) % 16 == 0 and padded_text[-1] not in [chr(i) for i in range(1, 17)]:
        return padded_text

    # Get the last byte to determine the padding length
    padding_length = padded_bytes[-1]

    # Validate the padding length
    if padding_length > 16 or padding_length > len(padded_bytes):
        raise ValueError('Invalid padding length')

    # Ensure all padding bytes are consistent
    for i in range(1, padding_length + 1):
        if padded_bytes[-i] != padding_length:
            raise ValueError('Inconsistent padding bytes')

    # Remove the padding
    unpadded_bytes = padded_bytes[:-padding_length]

    # Convert the unpadded bytes back to a string
    return unpadded_bytes.decode('utf-8')

