### Backend (Flask)

```python
from flask import Flask, request, jsonify
import re
import os
from werkzeug.utils import secure_filename
import random

app = Flask(__name__)

UPLOAD_FOLDER = 'uploads'
ALLOWED_EXTENSIONS = {'txt'}

app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def extract_ingredients(recipe_text):
    pattern = r'^\d+\.\s*(.*)$|^•\s*(.*)$'
    ingredients = re.findall(pattern, recipe_text, re.MULTILINE)
    ingredients = [ingredient[0] or ingredient[1] for ingredient in ingredients]
    return ingredients

def generate_spell(ingredients):
    spell_parts = ["Mix ", "Stir ", "Boil ", "Chant ", "Brew "]
    spell_effects = ["for wisdom", "to summon luck", "for prosperity", "to ward off evil"]
    spell = random.choice(spell_parts) + ', '.join(ingredients) + ' ' + random.choice(spell_effects)
    return spell

@app.route('/api/generate-spell', methods=['POST'])
def api_generate_spell():
    if 'recipeFile' in request.files:
        file = request.files['recipeFile']
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            file_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            file.save(file_path)
            with open(file_path, 'r') as f:
                recipe_text = f.read()
        else:
            return jsonify({'error': 'Invalid file type'}), 400
    else:
        recipe_text = request.form.get('recipeText', '')

    ingredients = extract_ingredients(recipe_text)
    spell = generate_spell(ingredients)
    return jsonify({'spell': spell})

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)
    app.run(debug=True)
```

