```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <ftw.h>
#include <errno.h>

#define MAX_EXTENSIONS 6
#define PATH_MAX 4096

// Function to check if a file has one of the excluded extensions
int is_excluded(const char *filename, const char *extensions[], int count) {
    for (int i = 0; i < count; i++) {
        if (strstr(filename, extensions[i]) != NULL) {
            return 1;
        }
    }
    return 0;
}

// Callback function for nftw()
int process_file(const char *fpath, const struct stat *sb, int tflag, struct FTW *ftwbuf) {
    static char dest_path[PATH_MAX];
    static char *source_root = NULL;
    static char *dest_root = NULL;
    static const char *extensions[MAX_EXTENSIONS];
    static int ext_count = 0;
    static int action = 0; // 0 for copy, 1 for move

    if (tflag == FTW_D) { // Directory
        snprintf(dest_path, PATH_MAX, "%s/%s", dest_root, fpath + strlen(source_root));
        if (mkdir(dest_path, sb->st_mode) == -1 && errno != EEXIST) {
            perror("mkdir");
            return -1;
        }
    } else if (tflag == FTW_F && !is_excluded(fpath, extensions, ext_count)) { // File and not excluded
        snprintf(dest_path, PATH_MAX, "%s/%s", dest_root, fpath + strlen(source_root));
        if (action == 0) { // Copy
            if (link(fpath, dest_path) == -1 && errno != EEXIST) {
                perror("link");
                return -1;
            }
        } else if (action == 1) { // Move
            if (rename(fpath, dest_path) == -1) {
                perror("rename");
                return -1;
            }
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s [source_dir] [destination_dir] [-cp|-mv] [extension_list]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *source_dir = argv[1];
    const char *dest_dir = argv[2];
    const char *option = argv[3];

    if (strcmp(option, "-cp") == 0) {
        action = 0;
    } else if (strcmp(option, "-mv") == 0) {
        action = 1;
    } else {
        fprintf(stderr, "Invalid option. Use -cp for copy or -mv for move.\n");
        exit(EXIT_FAILURE);
    }

    int ext_count = 0;
    for (int i = 4; i < argc && ext_count < MAX_EXTENSIONS; i++) {
        extensions[ext_count++] = argv[i];
    }

    // Check if source directory exists and belongs to home directory
    struct stat sb;
    if (stat(source_dir, &sb) == -1 || !S_ISDIR(sb.st_mode)) {
        fprintf(stderr, "Error: Source directory '%s' does not exist or is not a directory\n", source_dir);
        exit(EXIT_FAILURE);
    }

    char home_dir[PATH_MAX];
    if (getenv("HOME") == NULL) {
        fprintf(stderr, "Error: HOME environment variable not set\n");
        exit(EXIT_FAILURE);
    }
    snprintf(home_dir, PATH_MAX, "%s", getenv("HOME"));

    if (strncmp(source_dir, home_dir, strlen(home_dir)) != 0) {
        fprintf(stderr, "Error: Source directory '%s' does not belong to the home directory hierarchy\n", source_dir);
        exit(EXIT_FAILURE);
    }

    // Create destination directory if it does not exist
    if (stat(dest_dir, &sb) == -1) {
        if (mkdir(dest_dir, 0755) == -1) {
            perror("mkdir");
            exit(EXIT_FAILURE);
        }
    }

    if (nftw(source_dir, process_file, 20, FTW_DEPTH | FTW_PHYS) == -1) {
        perror("nftw");
        exit(EXIT_FAILURE);
    }

    if (action == 1) { // Move: remove source directory after move
        if (rmdir(source_dir) == -1) {
            perror("rmdir");
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}
```

### Explanation:

1. **Error Handling for Source Directory**:
   - We use `stat()` to check if the source directory exists and is indeed a directory.
   - We check if the source directory belongs to the home directory hierarchy by comparing the path prefix.

2. **Creating Destination Directory**:
   - If the destination directory does not exist, we create it using `mkdir()`.

3. **Using `nftw()` with `FTW_DEPTH`**:
   - The `FTW_DEPTH` flag ensures that directories are processed after their contents, making it easier to delete the source directory after moving.

4. **Deleting Source Directory**:
   - After moving files, we delete the source directory using `rmdir()`.

This implementation ensures that the source directory is correctly handled and that the program behaves as expected for both copy and move operations while excluding specified file types.

