3. Create the LL(1) parsing table.
4. Implement the parser to analyze input C code based on the grammar.

Here's how we can do that in Python:

```python
def compute_first_sets(grammar):
    first_sets = {symbol: set() for symbol in grammar}

    def compute(symbol):
        if symbol in first_sets and first_sets[symbol]:
            return first_sets[symbol]

        for production in grammar[symbol]:
            if production[0].islower() or production[0] == '@':
                first_sets[symbol].add(production[0])
            else:
                first_sets[symbol].update(compute(production[0]))

        return first_sets[symbol]

    for symbol in grammar:
        compute(symbol)

    return first_sets

def compute_follow_sets(grammar, first_sets, start_symbol):
    follow_sets = {symbol: set() for symbol in grammar}
    follow_sets[start_symbol].add('$')

    def update_follow(symbol, new_set):
        for item in new_set:
            if item != '@':
                follow_sets[symbol].add(item)

    for lhs in grammar:
        for production in grammar[lhs]:
            for i, symbol in enumerate(production):
                if symbol in grammar:
                    if i < len(production) - 1 and production[i + 1].isupper():
                        update_follow(symbol, first_sets[production[i + 1]] - {'@'})
                        if '@' in first_sets[production[i + 1]]:
                            update_follow(symbol, follow_sets[lhs])
                    elif i == len(production) - 1:
                        update_follow(symbol, follow_sets[lhs])

    return follow_sets

def generate_ll1_table(grammar, first_sets, follow_sets):
    table = {symbol: {} for symbol in grammar}

    for lhs in grammar:
        for production in grammar[lhs]:
            for symbol in first_sets[lhs]:
                if symbol in table[lhs]:
                    raise ValueError(f"Conflict in table at {lhs} -> {production} with {symbol}")
                table[lhs][symbol] = production

    for lhs in grammar:
        for symbol in follow_sets[lhs]:
            table[lhs].setdefault(symbol, [])

    return table

def parse_ll1(input_string, table, start_symbol):
    stack = ['$', start_symbol]
    input_string += '$'
    index = 0

    while stack:
        top = stack.pop()
        current = input_string[index]

        if top == current:
            index += 1
        elif top.isupper():
            if current not in table[top]:
                raise ValueError(f"Error at {current}, expected {', '.join(table[top].keys())}")
            production = table[top][current]
            if production:
                stack.extend(reversed(production))
        else:
            raise ValueError(f"Unexpected symbol {current}")

    return "Valid"

# Define the grammar
grammar = {
    'S': ['<ArithmeticExpression>', '<AssignmentExpression>', '<CommaExpression>', '<RelationalExpression>', '<LogicalExpression>'],
    '<ArithmeticExpression>': ['<Number> + <Number>', '<Number> - <Number>', '<Number> * <Number>', '<Number> / <Number>', '<Variable> + <Number>', '<Variable> - <Number>', '<Variable> * <Number>', '<Variable> / <Number>', '<Number> + <Variable>', '<Number> - <Variable>', '<Number> * <Variable>', '<Number> / <Variable>', '<Variable> + <Variable>', '<Variable> - <Variable>', '<Variable> * <Variable>', '<Variable> / <Variable>'],
    '<AssignmentExpression>': ['<Variable> = <ArithmeticExpression>', '<Variable> = <Number>'],
    '<CommaExpression>': ['<Expression>, <Expression>'],
    '<RelationalExpression>': ['<Number> < <Number>', '<Number> > <Number>', '<Number> <= <Number>', '<Number> >= <Number>', '<Number> == <Number>', '<Number> != <Number>', '<Variable> < <Number>', '<Variable> > <Number>', '<Variable> <= <Number>', '<Variable> >= <Number>', '<Variable> == <Number>', '<Variable> != <Number>', '<Number> < <Variable>', '<Number> > <Variable>', '<Number> <= <Variable>', '<Number> >= <Variable>', '<Number> == <Variable>', '<Number> != <Variable>', '<Variable> < <Variable>', '<Variable> > <Variable>', '<Variable> <= <Variable>', '<Variable> >= <Variable>', '<Variable> == <Variable>', '<Variable> != <Variable>'],
    '<LogicalExpression>': ['<RelationalExpression> && <RelationalExpression>', '<RelationalExpression> || <RelationalExpression>', '! <RelationalExpression>'],
    '<Expression>': ['<ArithmeticExpression>', '<AssignmentExpression>', '<CommaExpression>', '<RelationalExpression>', '<LogicalExpression>'],
    '<Number>': ['2'],
    '<Variable>': ['x'],
}

first_sets = compute_first_sets(grammar)
follow_sets = compute_follow_sets(grammar, first_sets, 'S')
ll1_table = generate_ll1_table(grammar, first_sets, follow_sets)

# Display the First and Follow sets
print("First Sets:")
for symbol, first_set in first_sets.items():
    print(f"{symbol}: {first_set}")

print("\nFollow Sets:")
for symbol, follow_set in follow_sets.items():
    print(f"{symbol}: {follow_set}")

# Display the LL(1) parsing table
print("\nLL(1) Parsing Table:")
for lhs, row in ll1_table.items():
